def _con_terminacion(nombre):
    """Devuelve el nombre con su terminacion .py, sin ponerla dos veces."""
    if nombre.endswith(".py"):
        return nombre
    return nombre + ".py"


def _huerfanas(raiz):
    """Devuelve la lista de piezas huerfanas de la casa, sin duplicados, con .py."""

def recien_nacidas(raiz, dias=2):
    """Devuelve las huerfanas que son NUEVAS, mirando la historia guardada.

    Se le pregunta a la historia (git) la fecha del primer guardado de cada archivo.
    Es nueva si esa fecha cae dentro de los ultimos 'dias', o si el archivo todavia
    no esta guardado en la historia. Si algo falla, devuelve lista VACIA.
    """
    try:
        huerfanas = _huerfanas(raiz)
    except Exception:
        return []
    nuevas = []
    for nombre in huerfanas:
        try:
            resultado = subprocess.run(
                ["git", "log", "--diff-filter=A", "--format=%ct", "--", nombre],
                cwd=raiz,
                capture_output=True,
                text=True,
                timeout=5,
            )
            salida = (resultado.stdout or "").strip()
            if not salida:
                nuevas.append(nombre)
                continue
            primera = int(salida.splitlines()[-1])
            import time
            if (time.time() - primera) <= dias * 86400:
                nuevas.append(nombre)
        except Exception:
            continue
    return nuevas


